mod portable {
    pub trait OsStringExt { fn from_vec(bytes: Vec<u8>) -> Self; }
    impl OsStringExt for std::ffi::OsString {
        fn from_vec(bytes: Vec<u8>) -> Self {
            String::from_utf8(bytes).expect("fixture is ASCII").into()
        }
    }
}
mod ported_dirs;
fn main() {
    let fixture = std::path::Path::new("target/netd-review-4/synthetic-user-dirs");
    std::fs::write(fixture, b"XDG_MUSIC_DIR=\"").unwrap();
    let panics = std::panic::catch_unwind(|| {
        ported_dirs::all(std::path::Path::new("/synthetic/home"), fixture)
    }).is_err();
    assert!(panics);
    println!("dirs-sys 0.5.0: single-quote XDG value causes parser panic={panics}; Windows portability shim changes only OsStringExt import");
    #[derive(enum_ordinalize::Ordinalize)]
    #[repr(u8)]
    enum Shifted { First = 1 << 2, Next }
    let actual = Shifted::Next as u8;
    let derived = Shifted::Next.ordinal();
    assert_eq!(actual, 5);
    assert_eq!(derived, 8);
    println!("enum-ordinalize 3.1.15: actual discriminant={actual}, derived ordinal={derived}, from_ordinal(5).is_none={}", Shifted::from_ordinal(5).is_none());
    let input = format!("{}.x", "a".repeat(254));
    let out = sanitize_filename::sanitize_with_options(&input, sanitize_filename::Options {
        windows: true, truncate: true, replacement: "",
    });
    let valid = sanitize_filename::is_sanitized_with_options(&out, sanitize_filename::OptionsForCheck {
        windows: true, truncate: true,
    });
    assert_eq!(out.len(), 255);
    assert!(out.ends_with('.'));
    assert!(!valid);
    println!("sanitize-filename 0.6.0: windows output length={}, trailing_dot={}, is_sanitized={valid}", out.len(), out.ends_with('.'));
    let mut encoding = data_encoding::HEXLOWER.clone();
    encoding.0 = (&[0xF6; 514][..]).into();
    let result = std::panic::catch_unwind(|| encoding.encode(&[1, 2, 3, 4]));
    match result {
        Ok(text) => {
            let invalid_utf8 = std::str::from_utf8(text.as_bytes()).is_err();
            println!("data-encoding 2.11.1: safe public field mutation produced invalid UTF-8 String={invalid_utf8}");
            assert!(invalid_utf8);
        }
        Err(_) => println!("data-encoding 2.11.1: corruption caught by enabled safety check"),
    }
}
